let audioContext=null,audioMuted=false;
ui.bgm.volume=.32;
function unlockAudio(){if(!audioContext)audioContext=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==="suspended")audioContext.resume();if(!audioMuted)ui.bgm.play().catch(()=>{});}
function sfx(kind){if(audioMuted)return;unlockAudio();const now=audioContext.currentTime,gain=audioContext.createGain(),osc=audioContext.createOscillator();osc.connect(gain).connect(audioContext.destination);const settings={popup:[620,920,.16,"sine"],flip:[360,720,.2,"triangle"],hit:[150,95,.11,"square"],hurt:[130,62,.24,"sawtooth"],explosion:[105,36,.42,"sawtooth"],chest:[440,1040,.5,"sine"],win:[520,1180,.7,"triangle"]}[kind]||[440,660,.12,"sine"];osc.type=settings[3];osc.frequency.setValueAtTime(settings[0],now);osc.frequency.exponentialRampToValueAtTime(settings[1],now+settings[2]);gain.gain.setValueAtTime(kind==="explosion"?.13:.07,now);gain.gain.exponentialRampToValueAtTime(.001,now+settings[2]);osc.start(now);osc.stop(now+settings[2]);if(kind==="explosion"){const buffer=audioContext.createBuffer(1,audioContext.sampleRate*.32,audioContext.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*Math.pow(1-i/data.length,2);const noise=audioContext.createBufferSource(),noiseGain=audioContext.createGain();noise.buffer=buffer;noiseGain.gain.setValueAtTime(.12,now);noiseGain.gain.exponentialRampToValueAtTime(.001,now+.32);noise.connect(noiseGain).connect(audioContext.destination);noise.start(now);}}
function toggleAudio(){audioMuted=!audioMuted;ui.bgm.muted=audioMuted;ui.audioToggle.classList.toggle("muted",audioMuted);ui.audioToggle.textContent=audioMuted?"\u266a":"\u266b";ui.audioToggle.title=audioMuted?"\u5f00\u542f\u97f3\u4e50":"\u5173\u95ed\u97f3\u4e50";ui.audioToggle.setAttribute("aria-label",ui.audioToggle.title);if(!audioMuted)unlockAudio();}

